-- =====================================================================
-- Saquarema Verde Online — banco de dados (Supabase)
-- Como usar: Supabase > SQL Editor > New query > cole este arquivo > Run.
-- É seguro rodar mais de uma vez.
-- =====================================================================

-- ---------- Quem é administrador ----------
-- O papel "admin" fica em app_metadata do usuário. Só o painel do Supabase ou
-- o SQL podem alterá-lo: o próprio usuário não consegue se promover.
create or replace function public.is_admin()
returns boolean
language sql stable
as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin', false);
$$;

-- ---------- Tabelas ----------
create table if not exists public.attractions (
  id bigint generated by default as identity primary key,
  name text not null,
  area text not null default 'Saquarema',
  type text not null default 'Trilha',
  difficulty text not null default 'Variada',
  distance text not null default 'A confirmar',
  hours text not null default 'A confirmar',
  status text not null default 'Aberta',
  trail_condition text not null default 'A informar',
  description text not null default '',
  tips text not null default '',
  rules text not null default '',
  image text not null default '/img/parque.svg',
  location text not null default '',
  address text not null default '',
  gallery jsonb not null default '[]'::jsonb,
  sources jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.events (
  id bigint generated by default as identity primary key,
  title text not null,
  event_date date not null,
  event_time text not null default '',
  place text not null default '',
  address text not null default '',
  status text not null default 'Aberto'
);

create table if not exists public.seasons (
  id bigint generated by default as identity primary key,
  name text not null,
  date_from date not null,
  date_to date not null,
  hours text not null default ''
);

create table if not exists public.news (
  id bigint generated by default as identity primary key,
  title text not null,
  body text not null default '',
  created_at timestamptz not null default now()
);

create table if not exists public.alerts (
  id bigint generated by default as identity primary key,
  message text not null,
  active boolean not null default true
);

-- Relatos enviados por visitantes (podem conter contato: só o admin lê)
create table if not exists public.reports (
  id bigint generated by default as identity primary key,
  place text not null check (char_length(place) <= 200),
  type text not null check (char_length(type) <= 60),
  body text not null check (char_length(body) between 1 and 500),
  contact text not null default '' check (char_length(contact) <= 200),
  status text not null default 'Novo',
  created_at timestamptz not null default now()
);

create index if not exists events_date_idx on public.events (event_date);
create index if not exists reports_created_idx on public.reports (created_at desc);

-- ---------- Regras de acesso (Row Level Security) ----------
-- Conteúdo do site: todos leem, só o administrador altera.
do $$
declare t text;
begin
  foreach t in array array['attractions', 'events', 'seasons', 'news', 'alerts'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "leitura publica" on public.%I', t);
    execute format('create policy "leitura publica" on public.%I for select to anon, authenticated using (true)', t);
    execute format('drop policy if exists "admin escreve" on public.%I', t);
    execute format('create policy "admin escreve" on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())', t);
    execute format('grant select on public.%I to anon, authenticated', t);
    execute format('grant insert, update, delete on public.%I to authenticated', t);
  end loop;
end $$;

-- Relatos: qualquer visitante envia (sempre como "Novo"); só o administrador lê, altera e apaga.
alter table public.reports enable row level security;
drop policy if exists "qualquer pessoa envia relato" on public.reports;
create policy "qualquer pessoa envia relato" on public.reports
  for insert to anon, authenticated with check (status = 'Novo');
drop policy if exists "admin gerencia relatos" on public.reports;
create policy "admin gerencia relatos" on public.reports
  for all to authenticated using (public.is_admin()) with check (public.is_admin());
grant insert on public.reports to anon, authenticated;
grant select, update, delete on public.reports to authenticated;

grant usage, select on all sequences in schema public to anon, authenticated;

-- ---------- Fotos (Storage) ----------
-- Bucket público para leitura; só o administrador envia, troca ou apaga. Máx. 3 MB, só imagens.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('fotos', 'fotos', true, 3145728, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = true, file_size_limit = 3145728, allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp'];

drop policy if exists "fotos leitura publica" on storage.objects;
create policy "fotos leitura publica" on storage.objects
  for select to anon, authenticated using (bucket_id = 'fotos');
drop policy if exists "fotos admin envia" on storage.objects;
create policy "fotos admin envia" on storage.objects
  for insert to authenticated with check (bucket_id = 'fotos' and public.is_admin());
drop policy if exists "fotos admin altera" on storage.objects;
create policy "fotos admin altera" on storage.objects
  for update to authenticated using (bucket_id = 'fotos' and public.is_admin()) with check (bucket_id = 'fotos' and public.is_admin());
drop policy if exists "fotos admin exclui" on storage.objects;
create policy "fotos admin exclui" on storage.objects
  for delete to authenticated using (bucket_id = 'fotos' and public.is_admin());

